def generate(seed):
    r = random.Random(seed)
    while True:
        W = r.randint(26, 32)
        pos = []
        i = 2
        while i <= W - 3:
            if r.random() < 0.5:
                pos.append(i)
                i += 3
            else:
                i += 1
        if not (6 <= len(pos) <= 9):
            continue
        g = ["_"] * W
        for c in r.sample(pos, r.randint(3, len(pos) - 3)):
            g[c] = "*"
        for c in pos:
            if g[c] == "_":
                g[c] = "Y"
        n = min(r.choice((1, 2, 2, 3, 3, 3)), len(pos) - 4)
        return "\n".join(["." * W] * r.choice((2, 3, 3)) + ["".join(g), str(n)])

