        for a, b in R:
            E |= {a - 1, b}; I |= {a, b - 1}; D |= set(range(a + 1, b - 1))
            for i in (a - 2, b + 1):
                if 0 <= i < W and not p[i]:
                    T.add(i)
        ed = [i for i in P if i in E]
