        loud = [len([i for i in P if p[i]]), len([i for i in P if not p[i]]), len(lw), len(tc),
                len([i for i in P if not p[i] and (i in E or i in T)]),
                len([i for i in P if (i and p[i - 1]) or (i + 1 < W and p[i + 1])]), sd, len(R)]
