                len([1 for a, b in R if [1 for i in P if a <= i < b]])]
        q = 3 * sum(v != n for v in loud) + sum(v != n for v in mild)
        q += 3 * bool(lw) + 3 * bool(tc) + bool(dp) + 4 * (sd != n)
        q += bool([1 for a, b in R if not (a - 1 in P or b in P)
                   and not [1 for i in P if a <= i < b]])
        if n > 1 and [1 for i in ed if g[i] == "*"] and [1 for i in ed if g[i] == "Y"]:
            q += 2
        if lw and tc:
            d = max(min(abs(u - v) for u in lw for v in ed),
                    min(abs(u - v) for u in tc for v in ed))
            q += 3 if d <= 9 else (1 if d <= 14 else 0)
        if q > bq:
